struct sock *sctp6_create_new_sock(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk;
    struct sctp_sock *new_sp, *sp;

    new_sk = sk_alloc(sk->sk_family, GFP_KERNEL, kern, 0);
    if (!new_sk)
        return NULL;

    new_sk->sk_type = sk->sk_type;
    new_sk->sk_protocol = sk->sk_protocol;
    new_sk->sk_rcvbuf = sk->sk_rcvbuf;
    new_sk->sk_sndbuf = sk->sk_sndbuf;

    new_sp = sctp_sk(new_sk);
    sp = sctp_sk(sk);

    memcpy(new_sp, sp, sizeof(struct sctp_sock));

    new_sp->asoc = asoc;
    new_sp->paddr.param.flags = 0;
    new_sp->paddr.param.address.ss_family = AF_INET6;

    if (sctp_init_sock(new_sk, sk, kern)) {
        sk_free(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct sctp6_sock *new_sctp6_sk;
    struct sctp_sock *new_sctp_sk;

    new_sk = sk_alloc(sk->net, PF_INET6, GFP_KERNEL, &sctp6_proto, kern);
    if (!new_sk)
        return NULL;

    new_sctp_sk = sctp_sk(new_sk);
    new_sctp6_sk = sctp6_sk(new_sk);

    new_sctp_sk->assoc = *asoc;

    new_sk->sk_type = sk->sk_type;
