    new_sk->sk_priority = sk->sk_priority;
    new_sk->sk_mark = sk->sk_mark;
    new_sk->sk_uid = sk->sk_uid;

    new_sctp6_sk->sctp6_sk_v6only = 1;

    if (sctp_sk_init(new_sk, sk->sk_net, sk->sk_net)) {
        sk_free(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct sctp6_sock *new_sctp6_sk;
    int err;

    new_sk = sk_alloc(sk->sk_family, GFP_KERNEL, kern);
    if (!new_sk)
        return NULL;

    new_sctp6_sk = (struct sctp6_sock *)new_sk;
    sctp_sk(new_sk)->asoc = *asoc;

    new_sk->sk_family = AF_INET6;
    new_sk->sk_protocol = IPPROTO_SCTP;
    new_sk->sk_type = SOCK_STREAM;

    err = sctp_sock_init(new_sk, sk);
    if (err) {
        sk_free(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct sctp6_sock *new_sctp6_sk;

    new_sk = sk_clone(sk, GFP_KERNEL);
    if (!new_sk)
        return NULL;

    new_sctp6_sk = (struct sctp6_sock *)new_sk;

    new_sctp6_sk->sctp.asoc = asoc;
    new_sctp6_sk->sctp.ep = asoc->ep;

    if (kern)
        new_sctp6_sk->sctp.opts = asoc->ep->a.opts;

    if (sctp6_init_sock(new_sk)) {
        sock_release(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk;
    struct sctp_sk *new_sctp_sk;
    int err;

    new_sk = sock_alloc();
    if (!new_sk)
        return NULL;

    sock_init_data(new_sk, NULL);
    new_sk->sk_family = AF_INET6;
    new_sk->sk_type = sk->sk_type;
    new_sk->sk_protocol = sk->sk_protocol;
    new_sk->sk_flags = sk->sk_flags;

    new_sctp_sk = sctp_sk(new_sk);
    new_sctp_sk->asoc = asoc;

    err = sctp_sock_options_copy(new_sk, sk);
    if (err < 0) {
        sock_release(new_sk);
        return NULL;
    }

    if (kern) {
        new_sk->sk_flags |= SOCK_ZAPPED;
    }

    return new_sk;
}
